// Original age-adapted explanations; existing teacher materials remain separate.
// Each entry: familiar situation, mechanism, worked example, question, feedback.
const escapeHtml = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const checkedSources = {
  solutions: '8-сынып оқулығы, §41 «Ерітінділердің концентрацияларын өрнектеу әдістері», 142-бет.',
  'reaction-rate': '9-сынып оқулығы, 1-бөлім, §14 «Химиялық реакциялардың жылдамдығы», 56-бет.',
  'industrial-equilibrium': '10-сынып оқулығы, 1-бөлім, §39 «Химиялық тепе-теңдік. Тепе-теңдік константасы», 159-бет.',
  'acid-base-ph': '11-сынып оқулығы, 2-бөлім, §52 «Қышқыл-негіздік теория», 45-бет.'
};
export function renderSchoolExplanation(unit) {
  const entry = EXPLANATIONS[unit.slug];
  if (!entry) return '';
  const [situation, mechanism, example, question, answer] = entry;
  return '<section class="school-explanation" aria-label="Қадаммен түсіну">'
    + '<h2>Қадаммен түсіну</h2><p>Таныс құбылысты түсіндіріп, мысалмен бекітейік.</p>'
    + [['Күнделікті өмірден', situation], ['Бұл қалай болады?', mechanism], ['Мысалды бірге талдайық', example]].map(([title, text], i) =>
      '<article class="school-question"><h3>' + (i + 1) + '. ' + title + '</h3><p>' + escapeHtml(text) + '</p></article>').join('')
    + '<article class="school-question"><h3>Өзің түсіндіріп көр</h3><p>' + escapeHtml(question)
    + '</p><details><summary>Жауабымды салыстыру</summary><p>' + escapeHtml(answer) + '</p></details></article>'
    + (checkedSources[unit.slug] ? '<p class="school-source">Тақырыпты оқулықтан қайталау: ' + escapeHtml(checkedSources[unit.slug]) + ' Жоғарыдағы өмірлік мысалдар — авторлық түсіндірме.</p>' : '')
    + '</section>';
}
